arguments.task_data_parsed:
{%- macro format_seconds(seconds) -%}
    {%- set hours = seconds // 3600 -%}
    {%- set minutes = (seconds % 3600) // 60 -%}
    {%- set remaining_seconds = seconds % 60 -%}
    {{ hours }}h {{ minutes }}m {{ remaining_seconds }}s
{%- endmacro -%}
{%- set empty = ['',Null,None] -%}
{%- set exec_results = vars.task_data -%}
{%- set results = {} -%}

{# set the default structure for the return #}
{%- set _do = results.update( {
  "error":True,
  "task_id":'',
  "task_data":{},
  "task_time": {
    "total_seconds":"",
    "total_time":""
  },
  "msg":"Task data is empty."
} ) -%}

{%- if exec_results.status is defined 
      and exec_results.task_response is defined 
      and exec_results.task_response not in empty
      and exec_results.task_response|length > 1 
-%}
  {%- if "task" in exec_results.execute_response -%}
    {%- set _do = results.update( 
        { "task_id":exec_results.execute_response.task } 
      ) 
    -%}
  {%- elif "taskid" in exec_results.execute_response -%}
    {%- set _do = results.update( 
        { "task_id":exec_results.execute_response.taskid } 
      ) 
    -%}
  {%- endif -%}
{%- endif -%}

{%- if exec_results.status is defined 
      and exec_results.task_response is defined 
      and exec_results.task_response not in empty
      and exec_results.task_response|length > 1 
-%}
     {# If we look to have task status
         and task response data we can parse it. 
     #}
  {%- set _do = results.update( 
      { "task_data":exec_results.task_response } 
    ) 
  -%}
  {%- set start_time = exec_results.task_response.start_tm -%}
  {%- set end_time = exec_results.task_response.end_tm -%}
  {%- if end_time == 0 -%}
    {%- set end_time = arrow.utcnow().int_timestamp -%}
  {%- endif -%}
  {%- set total_seconds = end_time-start_time -%}
  {%- set _do = results.update( { 
                        "task_time": {
                          "total_seconds":end_time-start_time,
                          "total_time":format_seconds(total_seconds)
                       } 
    } ) -%}
  {%- set line_cnt = 0 -%}  
  {%- if exec_results.task_response is defined 
        and exec_results.task_response.line not in empty 
  -%}
    {%- set line_cnt = exec_results.task_response.line|length -%}
  {%- endif -%}
  {%- if exec_results.status == 0 -%}
    {%- set _do = results.update( {"error":False} ) -%}
    {%- set msg = exec_results.task_response.title 
                         + " ( " + exec_results.task_response.state|default("unknown") + " ) "
                         + " -- " 
                         + exec_results.task_response.line[line_cnt-1].name|default("")
                         + " "
                         + exec_results.task_response.line[line_cnt-1].detail|default("") -%}
    {%- set _do = results.update( {"msg":msg}) -%}
    {%- if "error" in exec_results.task_response.state -%}
      {%- set _do = results.update( {"error":True} ) -%}
    {%- endif -%}
  {%- else -%}
    {%- set msg = results.msg -%}
    {%- if exec_results.task_response.msg is defined -%}
      {%- set msg = exec_results.task_response.msg -%}
      {%- if line_cnt > 0 -%}
        {%- set msg = msg 
                           + " -- " 
                           + exec_results.task_response.line[line_cnt-1].name|default("")
                           + " "
                           + exec_results.task_response.line[line_cnt-1].detail|default("") -%}
      {%- endif -%}
    {%- endif -%}
    {%- set _do = results.update( {"msg":msg}) -%}
  {%- endif -%}

{%- else -%}
  {%- if exec_results.task_response.msg is defined -%}
    {%- set _do = results.update( {"msg":exec_results.task_response.msg}) -%}
  {%- elif exec_results.error is defined -%}
    {%- set _do = results.update( {"msg":exec_results.error}) -%}
 {%- endif -%}
{%- endif -%}
{{results}}

arguments.status:
{%- set ret = vars.status -%}

{%- if vars.task_data_parsed.error -%}
  {%- do ret.update({
    "error":true,
    "message":vars.task_data_parsed.msg
  }) -%}
{%- endif -%}

{{ret}}

{# Set a default status #}
{%- set ret = {} -%}
{%- do ret.update({
  "error":false,
  "message":""
}) -%}
{{ret}}

arguments.task_timeout:
{%- set inp = vars.input.params['task_timeout'] -%}
{%- if inp not in ['',None] -%}
{{inp}}
{%- else -%}
21600
{%- endif -%}

arguments.task_stale_timeout:
{%- set inp = vars.input.params['task_stale_timeout'] -%}
{%- if inp not in ['',None] -%}
{{inp}}
{%- else -%}
120
{%- endif -%}

arguments.zero_percent_timeout:
{%- set inp = vars.input.params['zero_percent_timeout'] -%}
{%- if inp not in ['',None] -%}
{{inp}}
{%- else -%}
30
{%- endif -%}
